WITH flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) + INTERVAL 20 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM device_readings), islands AS (SELECT id, device_code, reading_ts, humidity, pressure, status_bits, firmware, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT CASE WHEN status_bits >= 12 THEN 'LARGE' ELSE 'SMALL' END AS status_bits_tier, MIN(reading_ts) AS first_seen, ROUND(SUM(session_id) / NULLIF(COUNT(CASE WHEN device_code = 'DV-02' THEN 1 END), 0), 2) AS session_id_per_dv_02 FROM islands GROUP BY CASE WHEN status_bits >= 12 THEN 'LARGE' ELSE 'SMALL' END;
